window.__saqPaperQuestions("2019-1-sa",[{"number":1,"title":"","stemText":"(18 marks) A 67 year old male patient was brought into the ED by his family after he collapsed at home. His past medical history includes dialysis-dependent chronic renal failure (secondary to diabetic nephropathy), hypertension, ischaemic heart disease and congestive cardiac failure. His initial vital signs in ED are as follows:\n\nGCS\n\nBP\n80/50 mmHg P bpm\n\nRR\n/min\n\nSpO2\n90%\n• n room air","parts":[{"id":"a","label":"Part A","prompt":"List four (4) specific point of care / bedside test which are indicated in this patient AND state your justifications (8 marks) Bedside tests Justification (4 marks) (4 marks)"},{"id":"b","label":"Part B","prompt":"An ECG is performed (see prop booklet). List three (3) diagnostic abnormalities in his ECG and state your unifying diagnosis (4 marks) ECG abnormalities Diagnosis (1 mark)"},{"id":"c","label":"Part C","prompt":"In view of the ECG findings, list three (3) ways you would correct the abnormality suggested by this ECG AND the treatment principle/goal for each (6 marks) Correct by: (drug and dose OR method) Treatment principle/goal (3 marks) (3 marks)"}],"propPages":["asset:imgb4073abd05d8a06923"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bedside U/S – pericardial tamponade, pulmonary oedema</div><div class=\"answer-line\">CXR – pulmonary oedema</div><div class=\"answer-line\">Blood gas – acid-base status  expect metabolic and respiratory acidosis</div><div class=\"answer-line\">Lactate – hypoperfusion, sepsis</div><div class=\"answer-line\">Hb – critical anaemia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Superior axis</div><div class=\"answer-line\">Sinoventricular rhythm / sine-wave morphology</div><div class=\"answer-line\"><strong>Diagnosis : critical hyperkalaemia</strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Stabilise myocardium : calcium chloride or calcium gluconate</td><td>Move K+ from extracellular to intracellular space : salbutamol, insulin / dextrose, bicarbonate</td></tr><tr><td>Remove K+ : haemodialysis</td><td>Pass marks a 7/8 b 3/4 c 4/6 total 14/18</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(18 marks) A 70 year-old female with a known seizure disorder has self-presented to your rural ED at 2\nam after brief <1min seizure (she lives several hours out of town with her husband).\nHer past history also includes middle cerebral artery stroke with NO residual focal deficits, hypertension and hypercholesterolaemia. Her seizure disorder is managed on levetiracetam and she has not had a seizure for 2 years.\nShe had missed 7 days of her anticonvulsants while she was travelling interstate.\nHer vital signs are:\n\nHR\nbpm\n\nBP\n130/70 mmHg\n\nSpO2\n97%\n• n room air\n\nRR\n/min\n\nTemp\n37.3 °C She has isolated right shoulder pain without evidence of injury in other locations. Her X-ray is included in the props booklet.","parts":[{"id":"a","label":"Part A","prompt":"Describe the findings on the X-Ray (2 marks)"},{"id":"b","label":"Part B","prompt":"List your three (3) treatment priorities for this patient with BRIEF details of each (6 marks) Management Priority Details"},{"id":"c","label":"Part C","prompt":"List three (3) important components of discharge planning for this patient with BRIEF details of each (6 marks) Discharge plan Details (3 marks) (3 marks) Prior to commencing any treatment the patient asks whether there are any likely complications from the injury."},{"id":"d","label":"Part D","prompt":"List four (4) potential complications from this injury. (4 marks)"}],"propPages":["asset:imgefdcc8fbd32773f0cf","asset:img9bc72e5df46f68b72c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Anterior shoulder dislocation</div><div class=\"answer-line\"></div><div class=\"answer-line\">Greater tuberosity fracture</div><div class=\"answer-line\"></div><div class=\"answer-line\"><strong>Must state direction of dislocation/Hills Sachs NOT an acceptable answer – zero score if </strong></div><div class=\"answer-line\"><strong>direction stated or incorrect direction of dislocation</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>(3 marks)</strong></td></tr><tr><td>Analgesia to facilitate assessment and</td><td>Appropriate therapy with oral (per pain</td></tr><tr><td>relieve symptoms</td><td>ladder)</td></tr><tr><td colspan=\"2\">Nitrous</td></tr><tr><td colspan=\"2\">IV opiates etc</td></tr><tr><td colspan=\"2\">MULTIPLE OPTIONS</td></tr><tr><td>Reduction of shoulder dislocation</td><td>Any appropriate method</td></tr><tr><td colspan=\"2\">- can attempt non sedated method e.g.</td></tr><tr><td colspan=\"2\">cunninghams</td></tr><tr><td colspan=\"2\">Appropriate sedatio and analgesia for given</td></tr><tr><td colspan=\"2\">method</td></tr><tr><td colspan=\"2\">NOTE: min displaced greater tuberosity</td></tr><tr><td colspan=\"2\">doesn’t preclude ED reduction – some</td></tr><tr><td colspan=\"2\">methods e.g. Kochers rely on an intact</td></tr><tr><td colspan=\"2\">greater tuberosity and are less suitable</td></tr><tr><td>Provision of anticonvulsant</td><td>Keppra 20mg/kg loading</td></tr><tr><td>loading/reinstitution of anticonvulsant</td><td>Or other alternative medication appropriate</td></tr><tr><td>therapy</td><td>Reinstitute previous dosing regimen</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">List three (3) important components of discharge planning for this patient with brief</td></tr><tr><td colspan=\"2\">details of each. <strong>(6 marks)</strong></td></tr><tr><td><strong>Discharge plan</strong></td><td><strong>Details</strong></td></tr><tr><td><strong>(3 marks)</strong></td><td><strong>(3 marks)</strong></td></tr><tr><td>Discharge advice</td><td>Wearing a sling for min 3 weeks/till seen in</td></tr><tr><td colspan=\"2\">fracture clinic</td></tr><tr><td colspan=\"2\">Active exercises of wrist and elbow +/- physio</td></tr><tr><td colspan=\"2\">Avoid abduction</td></tr><tr><td colspan=\"2\">Ensure that takes anticonvulsants/analgesic</td></tr><tr><td colspan=\"2\">regime</td></tr><tr><td>Appropriate follow up</td><td>Fracture clinic follow up in 1-2 weeks</td></tr><tr><td>(may be clumped in with discharge advice –</td><td>(this may be telehealth given rural location)</td></tr><tr><td>will gain both marks if so)</td><td>Neurology clinic/GP follow up for seizure</td></tr><tr><td colspan=\"2\">management</td></tr><tr><td>Counselling RE seizures and driving/other</td><td>Advise patient not to drive and notify MVR  -</td></tr><tr><td>safety measures/report to MVR</td><td>patient may be driving again as has been</td></tr><tr><td colspan=\"2\">seizure free on meds for several years</td></tr><tr><td colspan=\"2\">No swimming in sea/climbing ladders/other</td></tr><tr><td colspan=\"2\">dangerous pursuits</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Impingement of greater tuberosity fragment under the acromion – reduced ROM</td></tr><tr><td></td><td>Frozen shoulder</td></tr><tr><td></td><td>Axillary nerve damage – affects deltoid and teres minor so reduced abd and ext rotn</td></tr><tr><td colspan=\"2\">(other nerved radial/median/musulocut/ulnar/BP all are rare) – only allow max of</td></tr><tr><td colspan=\"2\">one mark of nerve injuries.</td></tr><tr><td></td><td>Rotator Cuff Injury</td></tr><tr><td></td><td>Ongoing Instability/Re-dislocation</td></tr><tr><td></td><td>Other soft tissue injuries e.g. glenoid tear</td></tr><tr><td></td><td>Axillary artery injury - rare</td></tr><tr><td colspan=\"2\">Pass marks a 2/2 b 4/6 c 4/6 d 3/4 total 13/18</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"(13 marks) A 28 year old, 32 week pregnant, woman presents to your regional hospital 20 minutes after being bitten by a snake on her foot. She is very anxious about the safety of her baby.","parts":[{"id":"a","label":"Part A","prompt":"State four (4) clinical syndromes associated with envenomation indicating an Australian snake which causes each (8 marks) Clinical Syndrome Causative Snake (4 marks) (4 marks)"},{"id":"b","label":"Part B","prompt":"State how the indication AND dose of antivenom are affected by this patient’s pregnant status with explanation (2 marks) You explain to the patient that you are going to organise transfer to a major hospital so she can continue to be managed. Upon hearing this she is quite distressed and requests that she stays at this small regional hospital."},{"id":"c","label":"Part C","prompt":"List the medical criteria that necessitate her transfer to the major hospital (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Coagulopathy – VICC (Venom induced</td><td>Brown, Tiger, Taipan</td></tr><tr><td colspan=\"2\">consumption coagulopathy)</td></tr><tr><td>Coagulopthy - Anticoagulant</td><td>Mulga/Black</td></tr><tr><td>Neurotoxicity</td><td>Death Adder, Taipan, Tiger, (Brown-</td></tr><tr><td colspan=\"2\">rare/mild)</td></tr><tr><td>Myotoxicity</td><td>Mulga, Tiger, Black (Taipan)</td></tr><tr><td>Systemic Symptoms (nausea, vomiting,</td><td>Tiger, Black, Death Adder, Taipan, Brown</td></tr><tr><td colspan=\"2\">headache, abdominal pain, diarrhoea,</td></tr><tr><td colspan=\"2\">diaphoresis)</td></tr><tr><td>Thrombotic microangiopathy</td><td>Brown, Tiger, Taipan</td></tr><tr><td>Cardiovascular Effects</td><td>Brown</td></tr><tr><td colspan=\"2\">NB – only 5 marks allocated (half mark for each box) as candidates could just state the 5</td></tr><tr><td colspan=\"2\">effects of either Brown or Tiger snake using these as their example of causative snake for</td></tr><tr><td colspan=\"2\">every syndrome.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Indication for antivenom unchanged</td></tr><tr><td></td><td>Dosage of antivenom unchanged</td></tr><tr><td></td><td>The volume of toxin to be neutralised is unchanged (as per dosage of antivenom for</td></tr><tr><td colspan=\"2\">children) and best care of mother is the best care of the baby</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Staff able and willing to manage snakebite management including definitive</td></tr><tr><td colspan=\"2\">treatment  of severe envenoming and treatment of potential complications</td></tr><tr><td></td><td>Lab facilities able to do Ix 24/7</td></tr><tr><td></td><td>Antivenom stocks adequate for definitive treatment in the right timeframe</td></tr><tr><td colspan=\"2\">Pass marks a 6/8 b 2/2 c 2/3 total 10/13</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"(12 marks)\nA 13 year old girl presents to the emergency department with confusion and abdominal\npain. She has a background of type 1 diabetes requiring insulin treatment.\nShe has had 3 days of vomiting and 2 days of diarrhoea prior to this presentation.\nHer vital signs are:\n\nTemp 37\n°C\n\nHR\n124 bpm\n\nBP\n120/70 mmHg Central capillary refill time 4 seconds Her initial venous blood gas results on room air are:\n\npH\n6.93\n\nNa\n124 mmol/L\n\npCO2\n9 mmHg\n\nK\n6.2 mmol/L\n\npO2\n44.9 mmHg\n\nCl\n79 mmol/L\n\nHCO3\n2 mmol/L Glc 43.5 mmol/L\n\nBE\n-25.5 mmol/L\n\nHb\n162 g/L","parts":[{"id":"a","label":"Part A","prompt":"Quote four (4) appropriate formulae that assist the analysis the above blood results. You are NOT required to insert the appropriate values or calculate results. (4 marks)"},{"id":"b","label":"Part B","prompt":"State four (4) important principles regarding your fluid and electrolyte treatment of this patient while in the emergency department AND give a justifying statement (which may include doses) for why it is an important principle (8 marks)\nPrinciple 1\nStatement 1\nPrinciple 2\nStatement 2\nPrinciple 3\nStatement 3\nPrinciple 4\nStatement 4"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Formula 1:</strong> Anion Gap = Na+ – (Cl- + HCO3</div><div class=\"answer-line\">-). Will also accept (Na+ + K+) – (Cl- + HCO3</div><div class=\"answer-line\">-)</div><div class=\"answer-line\"><strong>Formula 2:</strong> Corrected Na+ = [Na+] + [Glucose]/3</div><div class=\"answer-line\"><strong>Formula 3:</strong> Metabolic acidosis expected change in pCO2 = (1.5 x HCO3</div><div class=\"answer-line\">-) + 8</div><div class=\"answer-line\"><strong>Formula 4:</strong> Serum K decreases by 0.3mEq/L for every 0.1U increase in pH above normal.</div><div class=\"answer-line\"><strong>Formula 5: </strong>Delta ratio,  Delta Gap = Anion Gap – Baseline Gap (i.e. 12)</div><div class=\"answer-line\">Delta ratio = (Delta Gap (Increase in Anion Gap) /  Delta HCO3 (Decrease in bicarbonate))</div><div class=\"answer-line\">In DKA, ratio should be close to 1, due to loss of ketone acids in urine.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">this patient while in ED, and give a justifying statement (which may include doses) for</div><div class=\"answer-line\">why it is an important principle. <strong>(8 marks)</strong></div><div class=\"answer-line\">c.</div><div class=\"answer-line\">Rehydrate over 48 hours.</div><div class=\"answer-line\">a. Reason: patient 10% dehydrated and thus needs to be rehydrated slowly to</div><div class=\"answer-line\">ensure no rapid fluid/electrolyte shifts within body compartments. Fluid</div><div class=\"answer-line\">rehydration should include maintenance plus rehydration deficit</div><div class=\"answer-line\">replacement. Small bolus is OK.</div><div class=\"answer-line\">d. Start insulin infusion early (without bolus).</div><div class=\"answer-line\">a. Reason: need to start shifting glucose back into cells early in order to correct</div><div class=\"answer-line\">the acidosis (recommended rate 0.1u/kg/hr = 4u/hr)</div><div class=\"answer-line\">e. Monitor glucose fall closely.</div><div class=\"answer-line\">a. Reason (any of the following will be accepted): Often rapid falls in glucose are</div><div class=\"answer-line\">due to rapid fluid rehydration and thus the fluid rehydration rate may need</div><div class=\"answer-line\">to be slowed.</div><div class=\"answer-line\">b. Theoretical rapid glucose fall may result in cerebral oedema.</div><div class=\"answer-line\">f.</div><div class=\"answer-line\">Monitor potassium closely.</div><div class=\"answer-line\">a. Reason: fall in potassium will occur due to fluid rehydration plus addition of</div><div class=\"answer-line\">insulin. Need to ensure not too low to ensure cardiac activity is not</div><div class=\"answer-line\">compromised.</div><div class=\"answer-line\">Pass marks a 3/4 b 6/8 total 9/12</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"(12 marks)\nParents have brought their 3 year old child into your emergency department concerned that\nhe has inserted an uncooked kernel of popcorn into his right ear. Your examination confirms the presence of this foreign body (see photo in props booklet) The child is co-operative and well restrained by his parent.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) potential instruments/methods of removal OF THIS FOREIGN BODY including a “pro” and a “con” for each. (12 marks) 1)_________________________________________________________________________ Pro________________________________________________________________________ Con________________________________________________________________________ 2)_________________________________________________________________________ Pro________________________________________________________________________ Con________________________________________________________________________ 3)_________________________________________________________________________ Pro________________________________________________________________________ Con________________________________________________________________________ 4)_________________________________________________________________________ Pro________________________________________________________________________ Con________________________________________________________________________"}],"propPages":["asset:imgb653a393d6d08e86f9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pass mark 10/12</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"SAQ (11 marks)\nA febrile 72 year-old lady is brought by ambulance to ED with an acute abdomen.\nShe is known to have end-stage renal disease (secondary to diabetes) that is managed with chronic ambulatory peritoneal dialysis (CAPD). She has no allergies and is MRSA positive. You are concerned she has CAPD-associated peritonitis.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) possible causes for this patient to have abdominal pain and fever EXCLUDING CAPD-associated peritonitis (5 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table below by stating findings specific to CAPD-associated peritonitis. Findings History Examination The patient has an acute abdomen but is normotensive and responding normally."},{"id":"c","label":"Part C","prompt":"State your 3 most important pharmacological treatments for this lady. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bowel perforation (Cx of diverticular disease or colonic malignancy, perforated PUD)</div><div class=\"answer-line\">biliary sepsis</div><div class=\"answer-line\">ischaemic gut</div><div class=\"answer-line\">appendicitis</div><div class=\"answer-line\">urosepsis</div><div class=\"answer-line\">a. Complete the table below by stating findings specific to CAPD-associated peritonitis.</div><div class=\"answer-line\"><strong>(3 marks)</strong></div><div class=\"answer-line\"><strong>Findings</strong></div><div class=\"answer-line\"><strong>History</strong></div><div class=\"answer-line\">gradual onset and constant pain (not colicky)</div><div class=\"answer-line\">cloudy dialysate bags</div><div class=\"answer-line\"><strong>Examination</strong></div><div class=\"answer-line\">generalised tenderness</div><div class=\"answer-line\">Generalised signs of peritonism- no focal peritonitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">A febrile 72 year-old lady is brought by ambulance to ED with an acute abdomen.</div><div class=\"answer-line\">She is known to have end-stage renal disease (secondary to diabetes) that is managed with</div><div class=\"answer-line\">chronic ambulatory peritoneal dialysis (CAPD).</div><div class=\"answer-line\">She has no allergies and is MRSA positive.</div><div class=\"answer-line\">You are concerned she has CAPD-associated peritonitis.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>(abx dosing not essential but the route is)</em></div><div class=\"answer-line\">Pass mark a 4/5 b 2/3 c 2/3 total 8/11</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(14 marks) You have been informed of the results of an audit which demonstrate an increase in IV-line infections in your emergency department. You have been asked to find solutions to this problem.","parts":[{"id":"a","label":"Part A","prompt":"Given the three (3) factors below, list two (2) examples of each that may contribute to an increase in IV line infections (6 marks) Examples System factors Process factors Patient factors"},{"id":"b","label":"Part B","prompt":"List the key steps that can be used to prevent OR minimise these events occurring, with an example for each (8 marks) Steps Example"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List the factors which may contribute to an increase in IV line infections, with an</div><div class=\"answer-line\">example for each (6 marks)</div><div class=\"answer-line\">a. System factors</div><div class=\"answer-line\">i.  Lack of training in aseptic technique for insertion – hand hygiene,</div><div class=\"answer-line\">gloves, preparation of site with chlorhexidine, lack of availability of</div><div class=\"answer-line\">appropriate equipment, lack of guidelines/policy on reducing IV line</div><div class=\"answer-line\">associated infections</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>i. Alcohol gel/handwashing not readily available, procedures/policy not</td><td></td></tr><tr><td>followed for aseptic tecnqiue,  cannula not replaced at appropriate</td><td></td></tr><tr><td>interval, incorrect site selection for cannula, need for cannula not</td><td></td></tr><tr><td>established</td><td></td></tr><tr><td>c.</td><td>Patient factors</td></tr><tr><td>i. increasing severity of illness, granulocytopenia, compromised</td><td></td></tr><tr><td>integrity of the skin, and presence of distant infection.</td><td></td></tr><tr><td>b)</td><td>List the key steps that can be used to prevent or minimise these events occurring,</td></tr><tr><td>with an example for each. (8 marks)</td><td></td></tr><tr><td>QI cycle –</td><td></td></tr><tr><td>a. Plan</td><td></td></tr><tr><td>i. Review of existing guidelines with involvement of ED/non-ED</td><td></td></tr><tr><td>stakeholders, creation and implementation of a documented</td><td></td></tr><tr><td>departmental process that emphasises aseptic technique</td><td></td></tr><tr><td>b. Do</td><td></td></tr><tr><td>i. Education and enforcement of aseptic technique guidelines with spot</td><td></td></tr><tr><td>checks, address specific process, individual and system factors</td><td></td></tr><tr><td>c.</td><td>Check</td></tr><tr><td>i. Further audits and revision of processes</td><td></td></tr><tr><td>d. Act</td><td></td></tr><tr><td>i. Early detection systems/prevention of further problems, continue to</td><td></td></tr><tr><td>check/maintain compliance with policy</td><td></td></tr><tr><td><strong>Pass mark a 4/6 b 6/8 total 10/14</strong></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"(12 marks)\nA 25 year old athlete is brought to your Emergency Department by a voluntary St Johns\nambulance crew. He collapsed while competing in a marathon event and has only received basic first aid. On arrival in the ED his vital signs are as follows:\n\nGCS\n(E3, V4, M4)\n\nTemp\n41.5\n• C\n\nHR\n140 bpm\n\nBP\n85/40 mmHg\n\nSpO2\n98%\n• n room air","parts":[{"id":"a","label":"Part A","prompt":"List the three (3) MOST LIKELY differential diagnoses for this patient’s presentation. (3marks)"},{"id":"b","label":"Part B","prompt":"Outline the three (3) INITIAL treatments that you would commence WITH target end- points. (3 marks) Blood tests are performed on the patient and some of the initial results are given below:\n\nHb\n185 g/L (115 - 165)\n\nWCC\nx10⌃9/L (3.5 - 11) Plt x10⌃9/L (150 - 450)\n\nNa\n146 mmol/L (135 - 145)\n\nK\n5.7 mmol/L (3.5 - 5)\n\nUrea\nmmol/L (2 - 7)\n\nCreatinine\n410 umol/L (60 - 110) CK 27,000 IU/L (60 - 220)"},{"id":"c","label":"Part C","prompt":"List the three (3) MOST IMPORTANT abnormalities AND explain their significance (3 marks)"},{"id":"d","label":"Part D","prompt":"Following these investigation results state your MOST IMPORTANT treatment principle for your ongoing treatment principle for this patient (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Compulsory: </strong>Environmental – <strong>heat stroke</strong>, heat exhaustion (low GCS suggests heat stroke)</div><div class=\"answer-line\"><strong>Any two of the following:</strong></div><div class=\"answer-line\">Metabolic – dehydration (likely), hypoglycaemia, thyroid storm, hyponatraenia</div><div class=\"answer-line\">Infection – serious bacterial infection including CNS</div><div class=\"answer-line\">Neurological – seizure, ICH</div><div class=\"answer-line\">Drug ingestion/withdrawal – amphetamines, anticholinergics, thyroxine, NMSyndrome</div><div class=\"answer-line\"><strong>Must have heat stroke to pass. </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. Rehydration</strong> – cool IV fluids 20ml/kg, rapid infusion (monitor for pulmonary oedema).  Ensure adequate</div><div class=\"answer-line\">circulating blood volume.</div><div class=\"answer-line\"><strong>2. Cooling</strong> – needs urgent cooling.  Describe suitable method of cooling AND target core temp</div><div class=\"answer-line\">Eg. Exposure, external cooling</div><div class=\"answer-line\">3. Support airway/breathing, Consider ETT – modified induction with drugs/doses</div><div class=\"answer-line\">4. Monitoring – continuous core temp, ECG, Urine output, Electrolytes, BSL</div><div class=\"answer-line\">5. Seek and treat alternative causes – look for : source of sepsis, trauma/drugs</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">acute renal impairment</td></tr><tr><td><strong>High CK</strong></td><td>rhabdomyolysis</td></tr><tr><td>High K+</td><td>ARF/muscle breakdown</td></tr><tr><td>Elevated Hb</td><td>Dehydration</td></tr><tr><td>Elevated WBC</td><td>Dehydration/infection</td></tr><tr><td>Low plt</td><td>tcp/DIC/coagulopathy</td></tr><tr><td colspan=\"2\"><strong>Must have 2 BOLD to pass</strong>.</td></tr><tr><td colspan=\"2\">Failure to note ARF AND Rhabdo = 1.5/3 maximum mark.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Treat Rhabdomyolysis: IV fluid, consider urinary alkalinisation with bicarb, if not improving </strong></div><div class=\"answer-line\"><strong>may require dialysis.</strong></div><div class=\"answer-line\"><strong>Treat Acute Renal Impairment: IV fluid resuscitation and insertion IDC: </strong>target urine output 1-</div><div class=\"answer-line\">2ml/kg/hr.</div><div class=\"answer-line\">Correct coagulopathy/blood products, monitor U+E</div><div class=\"answer-line\">Empiric IV antibiotics</div><div class=\"answer-line\">Correct electrolyte abnormalities: appropriate IV fluid resuscitation</div><div class=\"answer-line\"><strong>Must have 2/3 bold to pass</strong>.</div><div class=\"answer-line\">Pass marks a 2/3 b 2/3 c 2/3 d 2/3 total 8/12</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"(12 marks)\nA 34 year male presents to the Emergency Department with a widespread blistering rash.","parts":[{"id":"a","label":"Part A","prompt":"EXCEPT for Stevens-Johnson Syndrome OR toxic epidermal necrolysis, give six (6) differential diagnoses in this patient (6 marks)"},{"id":"b","label":"Part B","prompt":"Give four (4) causes of Stevens-Johnson Syndrome (4 marks)"},{"id":"c","label":"Part C","prompt":"What is Nikolsky’s sign? (2 marks) This space is intentionally blank"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Except  for  Stevens-Johnson  Syndrome  or  toxic  epidermal  necrolysis,  give  6</div><div class=\"answer-line\">differential diagnoses in this patient? (6 marks)</div><div class=\"answer-line\">Sunburn</div><div class=\"answer-line\">Kawasaki syndrome</div><div class=\"answer-line\">Toxic shock syndrome</div><div class=\"answer-line\">Staphylococcal scalded skin</div><div class=\"answer-line\">Erythema multiforme</div><div class=\"answer-line\">Pemphigoid (or bullous pemphigoid)</div><div class=\"answer-line\">Pemphigus (or pemphigus vulgaris)</div><div class=\"answer-line\">Subcorneal pustular dermatosis</div><div class=\"answer-line\">Insect bites</div><div class=\"answer-line\">Mustard gas</div><div class=\"answer-line\">Boric acid toxicity</div><div class=\"answer-line\">Herpes simplex</div><div class=\"answer-line\">Herpes zoster</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Herpes simplex</div><div class=\"answer-line\">Mycoplasma</div><div class=\"answer-line\">CMV</div><div class=\"answer-line\">Penicillins</div><div class=\"answer-line\">Cephalosporins</div><div class=\"answer-line\">Sulphonamides</div><div class=\"answer-line\">Phenytoin</div><div class=\"answer-line\">Carbamazepine</div><div class=\"answer-line\">Allopurinol</div><div class=\"answer-line\">Lamotrigine</div><div class=\"answer-line\">NSAIDs especially oxicams</div><div class=\"answer-line\">Immunisations</div><div class=\"answer-line\">Paracetamol (rare)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Epidermis detaches from the dermis/burn bed with slight friction or rubbing of the skin with</div><div class=\"answer-line\">finger</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"(18 marks)\nA 16 year old woman is brought to the emergency department by her parents who are\nconcerned about her recent loss of weight. She is known to have an eating disorder and\ncurrently has a BMI of 15.","parts":[{"id":"a","label":"Part A","prompt":"List nine (9) SIGNIFICANT complications of anorexia nervosa (9 marks) An arterial blood gas is performed on room air and the results are:\n\npH\n7.53\n\nCl\n\npCO2\nBase Excess 25.3\n\nNa\n131\n\nHCO3\n\nK\n2.2"},{"id":"b","label":"Part B","prompt":"List three (3) SIGNIFICANT abnormalities shown (3 marks)"},{"id":"c","label":"Part C","prompt":"What would be the causes for the abnormalities (2 marks) An ECG is performed (see prop booklet)."},{"id":"d","label":"Part D","prompt":"List the SIGNIFICANT findings on the ECG (3 marks)"},{"id":"e","label":"Part E","prompt":"List one (1) SIGNIFICANT arrhythmia this patient is at risk of? (1 mark)"}],"propPages":["asset:img4dea60c8e667b0924f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">2.2</td></tr><tr><td>Cl</td><td>75</td></tr><tr><td>Base Excess</td><td>25.3</td></tr><tr><td>HCO3</td><td>48</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Prolonged vomiting causing hydrogen ion loss causing metabolic alkalosis</strong></div><div class=\"answer-line\"><strong>Malnutrition and poor intake causing hypokalaemia</strong></div><div class=\"answer-line\">An ECG is performed and shown below</div><div class=\"answer-line\">What are the significant findings shown on ECG? (3 Marks)</div><div class=\"answer-line\"><strong>ST depression with T wave inversion and U waves</strong></div><div class=\"answer-line\"><strong>Significantly Prolonged QU interval</strong></div><div class=\"answer-line\"><strong>Consistent with severe hypokalaemia</strong></div><div class=\"answer-line\">What significant arrhythmia is this patient at risk of? (1 Mark)</div><div class=\"answer-line\"><strong>Ventricular arrhythmias VT, VF, Torsades de Pointes</strong></div><div class=\"answer-line\">The patient is admitted nutritional rescue.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Primary Metabolic Alkalosis with secondary respiratory alkalosis</strong></div><div class=\"answer-line\"><strong>Mild hyponatraemia</strong></div><div class=\"answer-line\"><strong>Severe hypokalaemia</strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">What is the likely underlying cause? (2 marks)</div><div class=\"answer-line\"><strong>Prolonged vomiting causing hydrogen ion loss causing metabolic alkalosis</strong></div><div class=\"answer-line\"><strong>Malnutrition and poor intake causing hypokalaemia</strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">An ECG is performed and shown below</div><div class=\"answer-line\"><strong>ST depression with T wave inversion and U waves</strong></div><div class=\"answer-line\"><strong>Significantly Prolonged QU interval</strong></div><div class=\"answer-line\"><strong>Consistent with severe hypokalaemia</strong></div><div class=\"answer-line\"><strong>Ventricular arrhythmias VT, VF, Torsades de Pointes</strong></div><div class=\"answer-line\">The patient is admitted nutritional rescue.</div><div class=\"answer-line\">What are the major electrolyte abnormalities associated with refeeding syndrome? (3 Marks)</div><div class=\"answer-line\"><strong>Hypokalaemia</strong></div><div class=\"answer-line\"><strong>Hypomagnesaemia</strong></div><div class=\"answer-line\"><strong>Hypophosphataemia</strong></div><div class=\"answer-line\">What vitamin is also deficient must be supplemented ? (1 Mark)</div><div class=\"answer-line\"><strong>Thiamine B1</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"(16 marks) An eight (8) year old boy presents with right thigh pain after falling two (2) meter out of a tree. Primary survey is unremarkable. He has obvious swelling of his right thigh, but no\n• ther apparent injuries. An XR reveals a mid-shaft femur fracture that is off-ended and\nsignificantly shortened. As part of his management the senior registrar decides to perform a femoral nerve block with ultrasound guidance. They use 20ml of 0.75% Ropivacaine.","parts":[{"id":"a","label":"Part A","prompt":"What is the MAXIMUM safe dose of ropivocaine for this child with an estimated\n\nweight of 30kg? (1 mark)"},{"id":"b","label":"Part B","prompt":"Outline the clinical features of local anaesthetic toxicity (6 marks) Early symptoms Severe toxicity"},{"id":"c","label":"Part C","prompt":"The patient shows signs of SEVERE toxicity. List five (5) treatment options AND your reason for that option (5 marks) Treatment option Reason"},{"id":"d","label":"Part D","prompt":"List four (4) measures to improve safety of nerve blocks in your department (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">An 8yo boy presents with right thigh pain after falling 2m out of a tree. Primary survey is</div><div class=\"answer-line\">unremarkable. He has obvious swelling of his right thigh, but no other apparent injuries.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">An XR reveals a midshaft  # femur, that is off-ended and significantly shortened.</div><div class=\"answer-line\">As part of his management the registrar decides to perform a femoral nerve block.  They use 20ml of</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">0.75% Ropivocaine, with ultrasound guidance.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":12,"title":"","stemText":"(12 marks) A 4- year old boy presents to your emergency department with a 2 day history of a rash (see photos in prop booklet)\nHis vital signs are\n\nHR\n145 bpm\n\nRR\n/min\n\nSpO2 98%\n• n room air\n\nTemp 39.5\n°C","parts":[{"id":"a","label":"Part A","prompt":"What is the MOST likely diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"List two (2) characteristic features of this rash (2 marks)"},{"id":"c","label":"Part C","prompt":"List two (2) features on your assessment OTHER THAN fever which may support your diagnosis (2 marks)"},{"id":"d","label":"Part D","prompt":"List three (3) key features of the management of this child (3 marks)"},{"id":"e","label":"Part E","prompt":"How can you confirm your suspected diagnosis? (1 mark)"},{"id":"f","label":"Part F","prompt":"List three (3) possible complications of this disease (3 marks)"}],"propPages":["asset:img5db323c95232b2dc8e","asset:imge658a02ff785f692a8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Test</td><td>Pros</td><td>Cons</td></tr><tr><td>D dimer</td><td>-Readily available</td><td>-Use with Wells score not</td></tr><tr><td>-No radiation</td><td>validated in pregnancy</td><td></td></tr><tr><td>-possibly good negative</td><td>-“normal range” in late</td><td></td></tr><tr><td>predictive value in context of</td><td>pregnancy unknown</td><td></td></tr><tr><td>gestalt low pre-test</td><td>-poor positive predictive</td><td></td></tr><tr><td>probability- Negative result</td><td>value and often positive in</td><td></td></tr><tr><td>rule in PE preventing further</td><td>late pregnancy</td><td></td></tr><tr><td colspan=\"3\">invasive tests-controversial</td></tr><tr><td>Lower limb Doppler US</td><td>-No radiation</td><td>-Poor negative predictive</td></tr><tr><td>-Good positive predictive</td><td>value in pregnancy-</td><td></td></tr><tr><td>value-Positive result rule in</td><td>proximal/pelvic DVTs</td><td></td></tr><tr><td colspan=\"3\">PE preventing further</td></tr><tr><td colspan=\"3\">invasive tests</td></tr><tr><td>VQ scan</td><td>-Good negative and positive</td><td>-Radiation dose-higher dose</td></tr><tr><td>predictive value- PE rule in</td><td>than new generation CTPA</td><td></td></tr><tr><td colspan=\"3\">and rule out</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">radiation dose</div><div class=\"answer-line\">-poor accuracy in context of</div><div class=\"answer-line\">background lung disease</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">predictive value- PE rule in</div><div class=\"answer-line\">generation machine lower</div><div class=\"answer-line\">and rule out-probably better</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Lower limb Doppler US</td><td>-No radiation</td><td>-Poor negative predictive</td></tr><tr><td>-Good positive predictive</td><td>value in pregnancy-</td><td></td></tr><tr><td>value-Positive result rule in</td><td>proximal/pelvic DVTs</td><td></td></tr><tr><td colspan=\"3\">PE preventing further</td></tr><tr><td colspan=\"3\">invasive tests</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">VQ scan</div><div class=\"answer-line\">-Good negative and positive</div><div class=\"answer-line\">-Radiation dose-higher dose</div><div class=\"answer-line\">predictive value- PE rule in</div><div class=\"answer-line\">than new generation CTPA</div><div class=\"answer-line\">and rule out</div><div class=\"answer-line\">-Bladder accumulation of</div><div class=\"answer-line\">contrast with high foetal</div><div class=\"answer-line\">radiation dose</div><div class=\"answer-line\">-poor accuracy in context of</div><div class=\"answer-line\">background lung disease</div><div class=\"answer-line\">-indeterminant result forces</div><div class=\"answer-line\">further testing</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>CT pulmonary angiogram</td><td>-Good negative and positive</td><td>-Radiation dose- new</td></tr><tr><td>predictive value- PE rule in</td><td>generation machine lower</td><td></td></tr><tr><td>and rule out-probably better</td><td>dose than VQ scan</td><td></td></tr><tr><td colspan=\"3\">than VQ scan-could be</td></tr><tr><td colspan=\"3\">considered “gold standard”</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"(12 marks) A 34-year old woman presents to the ED. She is complaining of sudden onset of shortness of\nbreath. She is 32 weeks pregnant and G3P2. There are no other reported symptoms.\nShe is placed in a cubicle with cardiac monitoring.\nHer vital signs are:\n\nHR\n120 bpm\n\nBP\n145/95 mmHg\n\nRR\n/min\n\nSpO2\n93%\n• n room air\n\nTemp 37.6\n°C","parts":[{"id":"a","label":"Part A","prompt":"A 12-lead ECG is performed (see prop booklet). List two (2) abnormal findings from\nthis ECG (2 marks)"},{"id":"b","label":"Part B","prompt":"Your provisional diagnosis is pulmonary embolus. Please list one (1) “pro” AND one (1) “con” for each of the following tests (8 marks) Test Pros Cons D dimer Lower Limb Doppler US VQ scan CT pulmonary angiogram"},{"id":"c","label":"Part C","prompt":"A CTPA is performed. Review the two axial slices from the scan (see prop booklet) and list one (1) abnormal finding from each image (2 marks) Abnormal finding\nAxial slice 1\nAxial slice 2"}],"propPages":["asset:imgcf49fd568822f27e03","asset:img0e0f4eeb9ae24529a5","asset:img3f1b1ac70b8a144b18"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":14,"title":"","stemText":"(11 marks) You are a newly appointed consultant working in a regional ED. You have had a patient interaction a few days ago which is concerning you. You reviewed an elderly Aboriginal woman who presented with lethargy and shortness of breath. A work-up revealed severe renal impairment and a potassium of 7.2 mmol/L. The patient spoke almost entirely in her first language with her 14-year-old granddaughter acting as an interpreter. You felt you gave a comprehensive explanation of the diagnosis, plan and need for admission. The patient appeared to understand, nodding occasionally and saying “yes”. Unfortunately, 30 minutes later her nurse reported that both the patient and her grand- daughter had walked out of the hospital shortly after you left the bedside.","parts":[{"id":"a","label":"Part A","prompt":"What are four (4) suggestions to help prevent a similar situation occurring in the future? (4 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) department-wide strategies you could implement to ensure culturally safe medical care is available? (4 marks)"},{"id":"c","label":"Part C","prompt":"A culturally competent approach to health care requires specific skills, knowledge and attitudes. What are three (3) GENERAL principles of a culturally competent approach to health care that may help you to care for a similar patient? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Always use an accredited/formal translator, and never a child</strong></div><div class=\"answer-line\"></div><div class=\"answer-line\">Early involvement of Aboriginal Health Workers or Liaison Officers</div><div class=\"answer-line\"></div><div class=\"answer-line\">These workers are <em>not</em> synonymous with translators</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">You are a newly appointed consultant working in a regional ED. You have had a patient</div><div class=\"answer-line\">interaction a few days ago which is concerning you.</div><div class=\"answer-line\">You reviewed an elderly Aboriginal woman who presented with lethargy and shortness of</div><div class=\"answer-line\">breath. A work-up revealed severe renal impairment and a potassium of 7.2 mmol/L.</div><div class=\"answer-line\">The patient spoke almost entirely in her first language with her 14-year-old granddaughter</div><div class=\"answer-line\">acting as an interpreter. You felt you gave a comprehensive explanation of the diagnosis,</div><div class=\"answer-line\">plan and need for admission. The patient appeared to understand, nodding occasionally and</div><div class=\"answer-line\">saying “yes”.</div><div class=\"answer-line\">Unfortunately, 30 minutes later her nurse reported that both the patient and her grand-</div><div class=\"answer-line\">daughter had walked out of the hospital shortly after you left the bedside.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Address non-medical needs (e.g. blankets, food, family)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"(12 marks) A six (6) month old boy is brought to the emergency department by his mother with 48 hours of vomiting and diarrhoea. His weight is 8 kg. He is alert on examination and his eyes are sunken, he has slightly dry mucous membranes and decreased skin turgor.\nHis vital signs are as follows:\n\nTemp\n36.5 °C\n\nHR\n140 bpm\n\nRR\n/min\n\nSpO2\n96%\n• n room air\n\nBGL\n4.5 mmol/L\n\nCapillary refill time <2 seconds\nYou diagnose him with gastroenteritis.","parts":[{"id":"a","label":"Part A","prompt":"What is his degree of dehydration? (1 mark)"},{"id":"b","label":"Part B","prompt":"Complete the table below for THIS child (8 marks) Nasogastric rehydration IV rehydration Indication (2 marks) Choice of rehydration fluid (2 marks) Rate of administration (ml/kg/hr) AND duration of therapy (4 marks)"},{"id":"c","label":"Part C","prompt":"List three (3) clinical signs that should be monitored during rehydration (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":16,"title":"","stemText":"(12 marks)\nA 78 year old gentleman presents to your major metropolitan Emergency Department after\nslipping over whilst putting out the bins. X-Rays reveal a left sided sub-capital fractured neck\n• f femur, however, fortunately there are no other injuries.\nYour registrar decides to use an ultrasound guided femoral nerve block to help manage the patient’s pain and asks for your help supervising.","parts":[{"id":"a","label":"Part A","prompt":"Using the US image obtained (see prop booklet) name the numbered structures in the table below (3 marks)\nStructure 1\nStructure 2\nStructure 3"},{"id":"b","label":"Part B","prompt":"Which structure is most lateral? (1 mark)"},{"id":"c","label":"Part C","prompt":"List the steps involved in performing an ultrasound guided femoral nerve block (8 marks)"}],"propPages":["asset:imgb14c493e2fe583d6d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":17,"title":"","stemText":"(12 marks) You are the consultant in a tertiary hospital ED. A 25 year old woman, G2P1 who is currently 20 weeks pregnant, attends the ED with a sore neck. She discloses to the resident that she was strangled by her partner during an altercation earlier in the evening. The resident comes to you for advice.","parts":[{"id":"a","label":"Part A","prompt":"What features of history OR examination would suggest her neck injury needs further investigation? (6 marks) After further assessment you decide the patient does NOT require specific investigation of her neck injury. She declines to stay in the ED for any further assessment as she was mainly worried about her neck."},{"id":"b","label":"Part B","prompt":"What are the important points to address prior to discharge of this patient? (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":18,"title":"","stemText":"(9 marks) You are a consultant working in a regional ED without speciality services or advanced imaging. An elderly man is bought to your ED after a fall the day prior. His daughter reports he tripped over whilst walking, and landed chin-first on the ground. She reports he has had difficulty mobilising since the fall. Your RMO has initially assessed the patient and X-rays of the C-spine is reported as showing ‘degenerative changes’. You are concerned about central cord syndrome.","parts":[{"id":"a","label":"Part A","prompt":"List the three (3) MOST COMMON findings on physical examination in this condition (3 marks)"},{"id":"b","label":"Part B","prompt":"State your plan for safe disposition of this patient (3 marks)"},{"id":"c","label":"Part C","prompt":"The daughter asks you what the prognosis for this condition is - what will you tell her? (1 mark)"},{"id":"d","label":"Part D","prompt":"List two (2) other causes of central cord syndrome besides trauma? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1.<span class=\"answer-source-red\"> Incomplete paralysis </span>(upper limb weakness <span class=\"answer-source-red\">greater than </span>the lower limb)</div><div class=\"answer-line\">2.<span class=\"answer-source-red\"> Incomplete sensory loss </span>(upper limbs <span class=\"answer-source-red\">greater than</span> the lower limbs)</div><div class=\"answer-line\">3.<span class=\"answer-source-red\"> Urinary retention</span>/bladder dysfunction</div><div class=\"answer-line\">/5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Apply <span class=\"answer-source-red\">C spine precautions</span>/immobilise</div><div class=\"answer-line\">2. Arrange immediate <span class=\"answer-source-red\">transfer to </span>closest referral centre with <span class=\"answer-source-red\">MRI </span></div><div class=\"answer-line\">3. Notify <span class=\"answer-source-red\">neurosurgical team </span>at referral centre of transfer</div><div class=\"answer-line\">/3</div><div class=\"answer-line\">c) The daughter is distraught and asks you what the prognosis for this condition is – what</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1.<span class=\"answer-source-red\"> Good prognosis</span> – most patients will ambulate and have some return of hand</div><div class=\"answer-line\">movement</div><div class=\"answer-line\">/1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1.<span class=\"answer-source-red\"> Tumour </span>(eg  syringomyelia or intramedullary tumor)</div><div class=\"answer-line\">2. Cervical <span class=\"answer-source-red\">spondylosis </span></div><div class=\"answer-line\">/2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"(18 marks) You receive a pre-alert from the ambulance service. They are bringing in a 78 year old male after fall from ladder with head and abdominal injuries. The vital signs en route are\n\nBP\n85 / 60 mmHg\n\nHR\n130 bpm, irregular\n\nGCS\nThe ambulance arrives with the patient. Primary survey confirms the pre-hospital findings and you find a bleeding scalp wound.\nHe has had 1L of NaCl 0.9%.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) of the most important classes of medications this patient might be taking that may alter your assessment or management of him? (4 marks)"},{"id":"b","label":"Part B","prompt":"In the following table list four (4) potential causes for his hypotension AND the most effective way you would diagnose the cause whilst still IN THE RESUSCITATION ROOM (4 marks) Cause How to diagnose"},{"id":"c","label":"Part C","prompt":"List five (5) common components of a massive transfusion pack (5 marks)"},{"id":"d","label":"Part D","prompt":"Apart from a normal INR/APTT list five (5) targets you would like to achieve to ensure adequate coagulation (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Anticoagulants</div><div class=\"answer-line\">2. Antiplatelets</div><div class=\"answer-line\">3. Negative chronotropic agents — BB, verapamil, amiodarone</div><div class=\"answer-line\">4. Anti-hypertensives</div><div class=\"answer-line\">5. Opioids</div><div class=\"answer-line\">6. Sedatives</div><div class=\"answer-line\">7 Kap agly Oeics ~ Se</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cause for Hypotension Most effective method to diagnose whilst</div><div class=\"answer-line\">still in the Resuscitation room</div><div class=\"answer-line\">Haemothorax CXR or eFAST</div><div class=\"answer-line\">Tension Pneumothorax Clinical exam Gr CXR</div><div class=\"answer-line\">L |</div><div class=\"answer-line\">Tamponade eFAST</div><div class=\"answer-line\">Intraperitoneal haemorrhage FAST</div><div class=\"answer-line\">Neurogenic Clinical exam</div><div class=\"answer-line\">Pelvic haemorrhage PXR</div><div class=\"answer-line\">Fe WA tr achype KR</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. PRBC</div><div class=\"answer-line\">2. FFP</div><div class=\"answer-line\">3. Platelets</div><div class=\"answer-line\">4. Cryoprecipitate</div><div class=\"answer-line\">5. Tranexamic acid</div><div class=\"answer-line\">6. Calcium chloride or gluconate</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1. lon Ca?*&gt; 1.1 mmol/L</div><div class=\"answer-line\">2. pH&gt;7.2</div><div class=\"answer-line\">3. Temperature &gt; 35</div><div class=\"answer-line\">4. Platelets &gt; 50x 10°/L</div><div class=\"answer-line\">5. Fibrinogen &gt;1.0g/L</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"(15 marks) Whilst you are at triage, a 3 month infant is brought to ED by his father. His father states that the infant has been sleepy all day and is not interested in feeds. He also reports the baby has also had a recent cough and a fever. The following observations are recorded\n\nRR\n14 /min and poor respiratory effort\n\nSpO2\n84%on room air\n\nHR\n50bpm\n\nBP\n95/50mmHg\n\nTemp 34.8°C\nThe infant appears pale, quiet, and is unresponsive. Faint bruising is noted on the cheeks.","parts":[{"id":"a","label":"Part A","prompt":"Describe your IMMEDIATE management of this infant (6 marks)"},{"id":"b","label":"Part B","prompt":"An urgent CT of his brain is performed (see prop booklet). Describe the relevant findings on the selected images provided (4 marks)"},{"id":"c","label":"Part C","prompt":"List two (2) other services that need to be informed because of these findings (2 marks)"},{"id":"d","label":"Part D","prompt":"The patient’s mother arrives in the department, visibly distraught. Outline your approach to explaining your findings to her (3 marks)"}],"propPages":["asset:img4824e88a6fd2090941","asset:img860978564f6d98ff6d","asset:img2aa715de5a1cfdd410","asset:imgfe15c348ac71aa6a47","asset:img96075e76d7eaa670da","asset:img70d0f4a700f0eac74f","asset:img8f169b006467871e37","asset:imgf7ec277be6b499ed99","asset:img67d69f9444c2ab2392","asset:img449ac234457b448326"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Move to appropriate resuscitation area.</div><div class=\"answer-line\">Assist ventilation with bag and mask to RR of 30/min.or 15:2 ratio</div><div class=\"answer-line\">Supplemental O2 to achieve SpO2 &gt; 90-92%</div><div class=\"answer-line\">Obtain vascular access or intraosseous within 2 minutes</div><div class=\"answer-line\">Urgent Glucose</div><div class=\"answer-line\">Intubation with rapid sequence approach unless becomes responsive with 02 or correction of</div><div class=\"answer-line\">hypoglycaemia</div><div class=\"answer-line\">Atropine if remains bradycardic or as intubation adjunct</div><div class=\"answer-line\">IV fluid bolus 10 or 20mi/kg</div><div class=\"answer-line\">Broad spectrum IV antibiotics Cefotaxime</div><div class=\"answer-line\">Obtain more detailed history</div><div class=\"answer-line\">b)An urgent CT of his Brain is performed</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">urosurgery consultation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">her 5 p with you - Char</div><div class=\"answer-line\">n Fc srity p n</div><div class=\"answer-line\">Openly disclose suspicion of NAI</div><div class=\"answer-line\">Inform of legal requirement to inform DCP and Child protection</div><div class=\"answer-line\">Additional notes re floppy baby case</div><div class=\"answer-line\">Initial impression is that of an infant who may have a respiratory complaint, but with no features of</div><div class=\"answer-line\">increased respiratory effort. However, the infant is floppy and unresponsive (U on AVPU scale), so</div><div class=\"answer-line\">immediate attention needs to be to secure an airway (esp. with history of vomiting as well) and</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">significantly aid response to treatment (e.g. Management in acute area/on large bed only</div><div class=\"answer-line\">exacerbates hypothermia leading to refractory arrhythmias).</div><div class=\"answer-line\">Specific care needs to be taken during intubation attempts (either soon after suctioning or during</div><div class=\"answer-line\">placement of ETT), not to cause undue vagal stimulation which may result in reflex bradycardia as</div><div class=\"answer-line\">this may falsely be interpreted as signs of raised ICP. Correct treatment therefore would be to</div><div class=\"answer-line\">commence ECM and give atropine IV/IO depending on access obtained. Adequate muscle relaxant</div><div class=\"answer-line\">and sedation (morph/midaz/fentanyl ) should be given prior to intubation.</div><div class=\"answer-line\">The candidate should realise that the history above does not adequately explain the life-threatening</div><div class=\"answer-line\">condition of this young infant with altered LOC. Sepsis should also be considered. ED Consultant</div><div class=\"answer-line\">assistance or code #33 called early. PICU/ Radiology warned. Neurosurgical Team specifically</div><div class=\"answer-line\">contacted. Social worker attendance requested if available.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"(12 marks)\nA 64-year-old lady, who recently emigrated from Sri Lanka, has presented with increasing\nshortness of breath and pleuritic chest pain on the background of 1 month of cough, intermittent fever and mild weight loss. She had recently completed a course of oral antibiotics form her GP. Chest x-ray revealed a moderate left-sided pleural effusion. A diagnostic tap has been performed, with the results available below: Macroscopic: Straw yellow Serum Results: Protein g/L Protein g/L Albumin g/L Albumin g/L Cholesterol 2.7 mmol/L LDH 327 U/L LDH 255 U/L\n\nWCC\n3987 x 10-6/L Polymorphs 28%\nMononuclear 72%","parts":[{"id":"a","label":"Part A","prompt":"List three (3) criteria that may help differentiate an exudate from a transudate effusion (3 marks)"},{"id":"b","label":"Part B","prompt":"List your three (3) most likely differential diagnoses based on the case and results above. (3 marks)"},{"id":"c","label":"Part C","prompt":"Apart from the pleural cell counts and biochemistry already performed, list three (3) additional investigations that are most likely to help determine the cause of the pleural effusion (3 marks)"},{"id":"d","label":"Part D","prompt":"List the three (3) most important aspects of the insertion of the needle into the pleural effusion to ensure a safe and effective therapeutic pleural tap. (3 marks) Do NOT list items that relate to consent or sterility of the procedure."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1.</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Light&#x27;s criteria:</div><div class=\"answer-line\">e Pleural fluid protein to serum protein ratio &gt;0.5</div><div class=\"answer-line\">¢ Pleural fluid LOH to serum LDH ratio &gt;0.6</div><div class=\"answer-line\">e Pleural fluid level &gt;2/3 of upper value for serum LDH</div><div class=\"answer-line\">® (optional) Serum albumin — pleural fluid albumin &lt;1.2g/dL</div><div class=\"answer-line\">e Pleural fluid albumin &gt; 30g/L</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">with the results available below:</div><div class=\"answer-line\">Macroscopic: Straw yellow Serum Results:</div><div class=\"answer-line\">Protein 44 g/L Protein 66 g/L</div><div class=\"answer-line\">Albumin 20 g/L Albumin 23 g/L</div><div class=\"answer-line\">Cholesterol 2.7 mmol/t. LDH 327 U/L</div><div class=\"answer-line\">LDH 255 U/L</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">WCC 3987.0 x10°/L</div><div class=\"answer-line\">Polymorphs 28%</div><div class=\"answer-line\">Mononuclear 72%</div><div class=\"answer-line\">1.</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Light&#x27;s criteria:</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">e Pleural fluid protein to serum protein ratio &gt;0.5</div><div class=\"answer-line\">¢ Pleural fluid LOH to serum LDH ratio &gt;0.6</div><div class=\"answer-line\">e Pleural fluid level &gt;2/3 of upper value for serum LDH</div><div class=\"answer-line\">® (optional) Serum albumin — pleural fluid albumin &lt;1.2g/dL</div><div class=\"answer-line\">e Pleural fluid albumin &gt; 30g/L</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"(13 marks)\nA 29 year old woman presents to the ED with a 6 hour history of mild abdominal cramping\nand vaginal bleeding for which she has used 2 sanitary pads over the 6 hours. Her last menstrual period was 8 weeks ago and she usually has a 28 day cycle. She is sexually active with a single long term partner and not using contraception as they are trying to start a family. She is concerned she is having a miscarriage.\nHer vital signs are:\n\nHR\nbpm\n\nBP\n120/74 mmHg\n\nT\n°C\n\nRR\n/min","parts":[{"id":"a","label":"Part A","prompt":"List three (3) of the most important factors that would increase her risk of ectopic pregnancy (3 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table below detailing vaginal examination findings in miscarriage (5 marks) Type of Miscarriage"},{"id":"c","label":"Part C","prompt":"List 3 criteria on pelvic US you would need to satisfy to safely exclude ectopic\npregnancy as the cause for her symptoms. (3 marks)"},{"id":"d","label":"Part D","prompt":"List 2 criteria on pelvic US that would characterise a pregnancy of uncertain location\n(2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Assisted reproductive technology (IVF)</div><div class=\"answer-line\">Previous ectopic pregnancy</div><div class=\"answer-line\">History of PID/salpingitis</div><div class=\"answer-line\">Abnormal uterine anatomy</div><div class=\"answer-line\">NOT — IUD, OCP, tubal ligation (increased risk of ectopic if pregnancy occurs whilst using</div><div class=\"answer-line\">them, but overall decreases the risk of a pregnancy being ectopic) — she is also trying to get</div><div class=\"answer-line\">Pregnant so would be unlikely to be using them.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">{must have both on each line to score 1 mark)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">|UP with fetal heart beat, yolk sac or fetal pole</div><div class=\"answer-line\">No abnormal adnexal mass visualised</div><div class=\"answer-line\">No increased pelvic free fluid</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Intrauterine sac without visible fetal heart beat, yolk sac or fetal pole</div><div class=\"answer-line\">No abnormal adnexal mass visualised</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"(12 marks) A 35-year old man of no fixed address presents to the ED with a complaint of a painful red eye for the past three days associated with worsening visual acuity. He is not forthcoming with more history. On initial inspection with the patient sitting up using normal light, you see the following (see prop booklet)","parts":[{"id":"a","label":"Part A","prompt":"List the four (4) MOST significant findings on the image (4 marks)"},{"id":"b","label":"Part B","prompt":"List the three (3) MOST important other aspects of the ocular evaluation which should be performed AND your expected findings (3 marks)"},{"id":"c","label":"Part C","prompt":"List the two (2) MOST important next steps in managing this patient (2 marks)"},{"id":"d","label":"Part D","prompt":"List three (3) possible complications of this if left untreated (3 marks)"}],"propPages":["asset:img8d9b933f3742c2f92d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Central corneal opacity</div><div class=\"answer-line\">Surrounding arcuate corneal opacity (appears raised) with possibly linear streaking medially</div><div class=\"answer-line\">Single eyelash that may be entropic causing corneal abrasion</div><div class=\"answer-line\">Small hypopyon in the anterior chamber</div><div class=\"answer-line\">Marked conjunctival injection especially laterally (difficult to see in this image) and around</div><div class=\"answer-line\">the limbus</div><div class=\"answer-line\">Slightly irregular pupil</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Visual acuity — likely significantly reduced due to central corneal opacity</div><div class=\"answer-line\">Intraocular pressure —likely normal or raised due to synechiae</div><div class=\"answer-line\">Examination under slit lamp — any one of - fluorescein uptake on ulcer, raised corneal,</div><div class=\"answer-line\">cells/flare in anterior chamber</div><div class=\"answer-line\">Corneal scraping for culture (central severe ulcer) — likely bacterial growth</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Urgent Ophthalmology referral</div><div class=\"answer-line\">Broad spectrum antibiotic drops (need broad spectrum to get mark)</div><div class=\"answer-line\">Analgesia (topical)</div><div class=\"answer-line\">Cycloplegics</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Opacification of the cornea and scarring (sight threatening)</div><div class=\"answer-line\">Synechiae formation</div><div class=\"answer-line\">Increased intraocular pressure /secondary glaucoma</div><div class=\"answer-line\">Corneal perforation of the cornea</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"(10 marks)\nA 78-year old man is brought to your ED by ambulance after a carer found him drowsy in\nbed this morning at 0900.\nThe patient admitted to taking 10 X 10mg temazepam capsules and a glass of whisky at 2200 the night before with the intent of ‘having a long sleep’. He denies ingestion of any other substances. He has a past history of hypertension and hypercholesterolaemia and a left sided MCA\ninfarct 8 months ago. He walks with the aid of a frame.\nHe is widowed and lives alone on a small farm on the outskirts of town.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) risk factors he has for a subsequent successful suicide attempt in the following month? (5 marks)"},{"id":"b","label":"Part B","prompt":"List five (5) ADDITIONAL risk factors for a subsequent suicide that you will be seeking when you assess him? (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Non disclosed attempt</div><div class=\"answer-line\">Male gender</div><div class=\"answer-line\">Age &gt;75 years</div><div class=\"answer-line\">Chronic disability/medical illness</div><div class=\"answer-line\">Potential social isolation {lives alone, social isolation)</div><div class=\"answer-line\">Examiners comments</div><div class=\"answer-line\">Better scoring candidates answered the question based on the facts presented in the stem.</div><div class=\"answer-line\">Lower scoring candidates made assumptions about the patient and their circumstances that may not</div><div class=\"answer-line\">have been true. These candidates also tended to state multiple examples of the same concept on</div><div class=\"answer-line\">separate lines, making it hard for them to gain marks. A few of these candidates also appeared to</div><div class=\"answer-line\">think that the current attempt means that he has had a previous attempt, despite there being no</div><div class=\"answer-line\">mention of a previous attempt in the question stem.</div><div class=\"answer-line\">There is a significant difference between alcoho! use and alcohol abuse - one glass of whisky is not</div><div class=\"answer-line\">evidence of alcohol abuse.</div><div class=\"answer-line\">Just because you live on a farm does not mean you automatically have access to firearms and high</div><div class=\"answer-line\">lethality poisons.</div><div class=\"answer-line\">Temazepam in the dose used is probably not a high lethality medication, even in a 78 year old with</div><div class=\"answer-line\">co-morbidities.</div><div class=\"answer-line\">Social isolation only scored one point, no matter how many examples of it were used.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Hopelessness</div><div class=\"answer-line\">Suicidal ideation</div><div class=\"answer-line\">Established plan</div><div class=\"answer-line\">Access to high risk means (e.g. beta blockers, firearms, high lethality substances (farmer))</div><div class=\"answer-line\">PHx Suicide attempt</div><div class=\"answer-line\">PHx Depression</div><div class=\"answer-line\">Alcohol/substance abuse</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"(14 marks) You are assessing an 84-year old female who has presented complaining of feeling dizzy. On examination she has nystagmus.","parts":[{"id":"a","label":"Part A","prompt":"Describe four (4) features of her nystagmus that suggest a central cause for her vertigo (4 marks)."},{"id":"b","label":"Part B","prompt":"Complete the following table of expected findings for her if she has central a central cause for her vertigo (4 marks) NON-nystagmus component of Findings in central vertigo (2 marks) the HINTS exam (2 marks)"},{"id":"c","label":"Part C","prompt":"List six (6) other findings on history or examination that are NOT part of the HINTS examination that suggest a central cause of vertigo (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Direction-changing</div><div class=\"answer-line\">Vertical or purely rotational direction</div><div class=\"answer-line\">Non fatiguable/sustained</div><div class=\"answer-line\">No latency to onset (&lt; 6 seconds after Dix Hallpike)</div><div class=\"answer-line\">Fixation does not inhibit or worsens</div><div class=\"answer-line\">Spontaneous</div><div class=\"answer-line\">Examiners comments</div><div class=\"answer-line\">Nystagmus can still change with movement when due to a central cause — it is just more obviously worse with</div><div class=\"answer-line\">head movement when peripheral.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>I Head impulse test ¢ Normal test — eyes remain on target or</td><td>* No saccadic correction</td></tr><tr><td>Test of skew * Vertical deviation seen</td><td>Examiners comments</td></tr><tr><td>The findings of each test were asked for (i.e. what would you see). “Positive” or “Negative” responses did not get</td><td>a mark.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Difficulty walking/ataxia</div><div class=\"answer-line\">Past pointing</div><div class=\"answer-line\">Dysdiadochokinesis</div><div class=\"answer-line\">Headache or neck pain</div><div class=\"answer-line\">Speech disturbance</div><div class=\"answer-line\">Visual loss</div><div class=\"answer-line\">Hypotonia</div><div class=\"answer-line\">Arm drift/rebound</div><div class=\"answer-line\">Normal hearing</div><div class=\"answer-line\">Non cranial nerve Vil or VIII deficits</div><div class=\"answer-line\">Sensory or motor limb deficits (both do not get 2 marks)</div><div class=\"answer-line\">No worsening on head movement</div><div class=\"answer-line\">Absent/minimal nausea or vomiting</div><div class=\"answer-line\">Examiners comments</div><div class=\"answer-line\">A positive Rhomberg’s test is more common with a vestibular (peripheral) cause, than a central one but is so</div><div class=\"answer-line\">poorly sensitive (c 20%) to not be of any use, so was not given a mark. It is also a test of proprioception, not of</div><div class=\"answer-line\">cerebellar or vestibular function.</div><div class=\"answer-line\">Hearing loss is more suggestive of a peripheral cause —a significant number of candidates incorrectly indicated it</div><div class=\"answer-line\">was suggestive of a central cause.</div><div class=\"answer-line\">Risk factors for cerebrovascular disease were not considered important enough to be given a mark. Many elderly</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"(11 marks)\nAn 8-year old boy fell and injured his elbow.","parts":[{"id":"a","label":"Part A","prompt":"Name three (3) ossification centres of the elbow you would expect to see on radiographs\nin a normal 8 year old boy. (3 marks)"},{"id":"b","label":"Part B","prompt":"List four (4) radiological features that you should look for in a patient that suggest the presence of a supracondylar fracture of the humerus. (4 marks)"},{"id":"c","label":"Part C","prompt":"List four (4) indications for reduction of a supracondylar fracture (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Capitellum</div><div class=\"answer-line\">Radial head</div><div class=\"answer-line\">Medial epicondyle</div><div class=\"answer-line\">Trochlea</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Supracondylar lucency suggestive of fracture line</div><div class=\"answer-line\">Cortical break on anterior surface of lower humerus on lateral view</div><div class=\"answer-line\">Anterior humeral line that does not bisect the capitellum on the lateral view</div><div class=\"answer-line\">Change in the angle between a line through the centre of the capitellum on the lateral</div><div class=\"answer-line\">view and the anterior humeral line</div><div class=\"answer-line\">Change in the between the physeal line of the lateral condyle of the humerus and a line</div><div class=\"answer-line\">perpendicular to the long axis of the humeral shaft (Bauman angle)</div><div class=\"answer-line\">Anterior fat pad sign</div><div class=\"answer-line\">Posterior fat pad sign</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Features of distal ischaemia</div><div class=\"answer-line\">&lt; 50% bony apposition in any direction</div><div class=\"answer-line\">Dorsal angulation &gt; 15 degrees</div><div class=\"answer-line\">Lateral or medial tilt &gt; 10 degrees</div><div class=\"answer-line\">Neurological injury</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"(12 marks)\nA 1 year old boy has been unwell with cough for a week. Today he was eating spaghetti\nwhen he seemed to gag and have difficulty breathing over a period of 1 minute. His mum reports he is now clingy with a ‘strange cough’. The following vital signs are recorded:\n\nHR\n120 bpm\n\nBP\n90/50 mmHg\n\nSpO2\n90%\n• n room air\n\nRR\n/min\n\nT\n37.5 °C\n\nWeight\nkg He is alert and responsive and comfortable in his mother’s arms. On physical examination he has multiple petechiae around his eyes, and an intermittent cough. He has mild indrawing of intercostal muscles and mild tracheal tug, but no stridor.","parts":[{"id":"a","label":"Part A","prompt":"Provide an explanation for the physical examination findings (not including the vital signs) (3 marks) Chest X-rays are performed (see props booklet)."},{"id":"b","label":"Part B","prompt":"List three (3) significant findings on the CXR (3 marks)"},{"id":"c","label":"Part C","prompt":"What is your diagnosis? (1 mark) After a short coughing spell the infant becomes cyanosed and unresponsive. No chest movement is obtained despite good self-inflating bag-and-mask ventilation. The child remains cyanosed and no oxygen saturations can be obtained. Chest thrusts have been given without effect."},{"id":"d","label":"Part D","prompt":"Outline your management of the infant’s airway (5 marks)"}],"propPages":["asset:img0ed453be3ff7c9036f","asset:img137790fe09a1571e04"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">VAG 27</div><div class=\"answer-line\">SAQ X Child with breathing difficulty (13 marks)</div><div class=\"answer-line\">A one year old boy has been unwell with cough for a week. Today he was eating spaghetti when he seemed</div><div class=\"answer-line\">to gag and have difficulty breathing over a period of 1 minute. His mum reports he is now clingy with a</div><div class=\"answer-line\">‘strange cough’.</div><div class=\"answer-line\">The following observations are recorded:</div><div class=\"answer-line\">HR 120</div><div class=\"answer-line\">Blood pressure 90/50</div><div class=\"answer-line\">Oxygen saturation 90% in air</div><div class=\"answer-line\">Respiratory rate 24</div><div class=\"answer-line\">Temp 37.5</div><div class=\"answer-line\">Weight 10kg</div><div class=\"answer-line\">On examination he is alert and responsive and comfortable in his mother’s arms.</div><div class=\"answer-line\">On examination he has multiple petechiae around his eyes, and an intermittent unusual cough.</div><div class=\"answer-line\">Cardiovascular examination is normal. He has mild indrawing of intercostal muscles and mild tracheal tug,</div><div class=\"answer-line\">but no stridor.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Mediastinal shift to the right on expiratory film</div><div class=\"answer-line\">Increased lucency left lung on expiration</div><div class=\"answer-line\">Hyperexpansion left lung on expiration</div><div class=\"answer-line\">Normal inspiratory film</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Inhaled foreign body in left main bronchus (needs correct side for both marks)</div><div class=\"answer-line\">After a short coughing spell the infant becomes cyanosed and unresponsive.</div><div class=\"answer-line\">No chest movement is obtained despite with good self inflating bag/ and mask ventilation. The child</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Attempt Bag/ and Mask ventilation with anaesthetic circuit (can generate higher pressures relative to self</div><div class=\"answer-line\">inflating bag)</div><div class=\"answer-line\">Perform direct laryngoscopy with Magills forceps on hand to remove foreign body</div><div class=\"answer-line\">Intubate if unable to remove F8 (adjust TV to prevent barotrauma as ventilation of only part of the lung</div><div class=\"answer-line\">may occur)— plan A</div><div class=\"answer-line\">Insert LMA — plan B</div><div class=\"answer-line\">Needle cricothyroidotomy if AB fails</div><div class=\"answer-line\">Insert above cricoid, below thyroid</div><div class=\"answer-line\">oxygenate with occlusion of Y connector on1 off 4 seconds</div><div class=\"answer-line\">To OT for EUA by ENT if able to adequately oxygenate</div><div class=\"answer-line\">Additonal notes</div><div class=\"answer-line\">Needle Technique ETM®:</div><div class=\"answer-line\">Setup for full RSI with paralytics</div><div class=\"answer-line\">If possible extend neck to allow better palpation of anatomy by placing a pillow well under the patient&#x27;s</div><div class=\"answer-line\">shoulders, allowing head/neck to extend — not possible if c-spine injury suspected</div><div class=\"answer-line\">if right handed, stand on patient’s left</div><div class=\"answer-line\">Draw 2-3ml of saline into Sml syringe</div><div class=\"answer-line\">Remove proximal end of flash chamber of 14G cannula and attach syringe to proximal end of cannula flash</div><div class=\"answer-line\">chamber</div><div class=\"answer-line\">Palpate the larynx with the left hand and find cricothyroid membrane with left index finger</div><div class=\"answer-line\">Approach skin with cannula at 30-45 degree angle, aiming toward patient’s feet with syringe over patient’s</div><div class=\"answer-line\">chin</div><div class=\"answer-line\">Aspirate on syringe as you advance cannula into trachea — successful entry into trachea signaled by</div><div class=\"answer-line\">aspirating air (seen as bubbles in the saline in syringe barrel)</div><div class=\"answer-line\">Advance the cannula off the needle into trachea</div><div class=\"answer-line\">Remove the needle from the syringe, and attach syringe to the orange hub of the cannula in the neck and</div><div class=\"answer-line\">perform a 2nd aspiration to confirm that air can still be aspirated and the cannula is still in trachea</div><div class=\"answer-line\">Attach oxygen delivery device to cannula</div><div class=\"answer-line\">If using a Rapid-O2 or LeRoy device deliver and initial 4-5 second jet of oxygen</div><div class=\"answer-line\">Wait 20 seconds to check for a response in oxygen saturation. If there is no response deliver a further 2</div><div class=\"answer-line\">second</div><div class=\"answer-line\">Base further delivery on oxygen on the oxygen saturation level: if the saturations drop by 5% or more,</div><div class=\"answer-line\">deliver further 2 second jets of oxygen.</div><div class=\"answer-line\">Cannula Insertion</div><div class=\"answer-line\">Jet ventilation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
